from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    current = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    result = []

    def add_if_valid(year, month, day):
        if 1 <= day <= calendar.monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= current:
                result.append(candidate)

    if kind == "DAILY":
        for i in range(count):
            result.append(current + timedelta(days=interval * i))

    elif kind == "WEEKLY":
        weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        week_start = current - timedelta(days=current.weekday())
        week_index = 0
        while len(result) < count:
            active_start = week_start + timedelta(weeks=week_index * interval)
            for weekday in selected:
                candidate = active_start + timedelta(days=weekday)
                if candidate >= current:
                    result.append(candidate)
                    if len(result) == count:
                        break
            week_index += 1

    elif kind == "MONTHLY":
        start_month_index = current.year * 12 + current.month - 1
        if len(parts) == 3:
            day = int(parts[2])
            month_index = start_month_index
            while len(result) < count:
                year, month0 = divmod(month_index, 12)
                month = month0 + 1
                last_day = calendar.monthrange(year, month)[1]
                candidate_day = last_day if day == -1 else day
                add_if_valid(year, month, candidate_day)
                month_index += interval
        else:
            nth = int(parts[2])
            weekday = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}[parts[3]]
            month_index = start_month_index
            while len(result) < count:
                year, month0 = divmod(month_index, 12)
                month = month0 + 1
                first_weekday, days_in_month = calendar.monthrange(year, month)
                if nth == -1:
                    last_weekday = date(year, month, days_in_month).weekday()
                    day = days_in_month - (last_weekday - weekday) % 7
                else:
                    day = 1 + (weekday - first_weekday) % 7 + (nth - 1) * 7
                add_if_valid(year, month, day)
                month_index += interval

    else:  # YEARLY
        month, day = map(int, parts[2].split("-"))
        year = current.year
        while len(result) < count:
            add_if_valid(year, month, day)
            year += interval

    return [d.isoformat() for d in result]
